import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String password = next(), reference = next();
        long[] cost = new long[26];
        for (int i = 0; i < 26; i++) cost[i] = nextLong();
        boolean[] removable = new boolean[26];
        for (int i = 0; i < reference.length(); i++) removable[reference.charAt(i) - 'a'] = true;
        long answer = 0;
        // Every occurrence of a reference letter must be deleted and pays its letter's cost.
        for (int i = 0; i < password.length(); i++) {
            int c = password.charAt(i) - 'a';
            if (removable[c]) answer += cost[c];
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	password, reference := next(), next()
	var cost [26]int64
	for i := range cost {
		cost[i] = nextInt()
	}
	var removable [26]bool
	for i := 0; i < len(reference); i++ {
		removable[reference[i]-'a'] = true
	}
	answer := int64(0)
	// Every occurrence of a reference letter must be deleted and pays its letter's cost.
	for i := 0; i < len(password); i++ {
		if c := password[i] - 'a'; removable[c] {
			answer += cost[c]
		}
	}
	fmt.Println(answer)
}
